  const a=head; let out:number[]=[];
  let previous:ListNode|null=null,node:ListNode|null=a;while(node){const next:ListNode|null=node.next;node.next=previous;previous=node;node=next;}for(node=previous;node;node=node.next)out.push(node.val);
